var gm = TerrainManager.build_area_group_map(TerrainManager.terrain_features)
var cats = {}
for p in TerrainManager.terrain_features:
	cats[str(p.id)] = TerrainManager.category_of(p)
return [gm["corner-ruin-balanced-right-13"] == gm["area-large-7"], gm["corner-short-15"] == gm["area-large-7"], gm["corner-ruin-balanced-right-14"] == gm["area-large-8"], cats["area-large-7"], cats["area-large-8"]]

var u = GameState.state["units"]["U_BOYZ_K"]
var n = 0
for m in u["models"]:
	if TerrainManager.is_model_hidden(m, u):
		n += 1
return n

var ms_boyz_k = GameState.state["units"]["U_BOYZ_K"]["models"]
var spots_boyz_k = [Vector2(1000.0, 1800.0), Vector2(1052.0, 1800.0), Vector2(1104.0, 1800.0), Vector2(1156.0, 1800.0), Vector2(1208.0, 1800.0), Vector2(1000.0, 1852.0), Vector2(1052.0, 1852.0), Vector2(1104.0, 1852.0), Vector2(1156.0, 1852.0), Vector2(1208.0, 1852.0)]
for i in range(ms_boyz_k.size()):
	ms_boyz_k[i]["position"] = spots_boyz_k[i]
var ms_custodian_guard_b = GameState.state["units"]["U_CUSTODIAN_GUARD_B"]["models"]
var spots_custodian_guard_b = [Vector2(1416.0, 968.0), Vector2(1480.0, 1000.0), Vector2(1384.0, 1032.0), Vector2(1352.0, 1096.0)]
for i in range(ms_custodian_guard_b.size()):
	ms_custodian_guard_b[i]["position"] = spots_custodian_guard_b[i]
node.get_node("Main")._sync_all_token_positions()
var n = 0
for m in GameState.state["units"]["U_CUSTODIAN_GUARD_B"]["models"]:
	var in_cluster = false
	for p in TerrainManager.pieces_model_within(m):
		if str(p.id) == "area-medium-29" or str(p.id) == "area-short-line-25":
			in_cluster = true
	if in_cluster:
		n += 1
return n
